t.script:
                // Initialize map centered on Vietnam with optimized settings
                const map = L.map('map', {
                    center: [21.0285, 105.8542], // Hanoi coordinates
                    zoom: 10, // Better zoom level to see markers clearly
                    zoomControl: true,
                    scrollWheelZoom: true,
                    doubleClickZoom: true,
                    boxZoom: true,
                    dragging: true,
                    keyboard: true,
                    touchZoom: true
                });

                // Add OpenStreetMap tile layer with performance optimizations
                L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                    attribution: '© OpenStreetMap contributors',
                    maxZoom: 16, // Reduced max zoom for better performance
                    minZoom: 4,
                    tileSize: 256,
                    zoomOffset: 0,
                    updateWhenZooming: false, // Performance optimization
                    updateWhenIdle: true, // Performance optimization
                    keepBuffer: 2, // Reduce memory usage
                    maxNativeZoom: 18
                }).addTo(map);

                // Store markers
                let markers = {};
                let autoRefreshInterval = null;
                let startMarkers = {};  // Lưu markers cho Start
                let destMarkers = {};   // Lưu markers cho Destination
                let allTripsData = [];
                let routeLines = {}; // Lưu các đường route đã vẽ

                // Custom icon for different statuses with driver and vehicle info
                // Toggle Active Trips List
                function toggleActiveTrips() {
                    const container = document.getElementById('active-trips-container');
                    const missingContainer = document.getElementById('missing-location-container');

                    if (container.classList.contains('active')) {
                        container.classList.remove('active');
                    } else {
                        container.classList.add('active');
                        missingContainer.classList.remove('active');
                        loadActiveTrips();
                    }
                }

                // Toggle Missing Location Trips List
                function toggleMissingLocationTrips() {
                    const container = document.getElementById('missing-location-container');
                    const activeContainer = document.getElementById('active-trips-container');

                    if (container.classList.contains('active')) {
                        container.classList.remove('active');
                    } else {
                        container.classList.add('active');
                        activeContainer.classList.remove('active');
                        loadMissingLocationTrips();
                    }
                }

                // Load Active Trips
                async function loadActiveTrips() {
                    try {
                        const response = await fetch('/web/dataset/call_kw/trucking_planning.trip/search_read', {
                            method: 'POST',
                            headers: {
                                'Content-Type': 'application/json',
                            },
                            body: JSON.stringify({
                                jsonrpc: '2.0',
                                method: 'call',
                                params: {
                                    model: 'trucking_planning.trip',
                                    method: 'search_read',
                                    args: [],
                                    kwargs: {
                                        domain: [
                                            ['is_current', '=', true],
                                            ['status', 'not in', ['cancelled', 'done']],
                                            ['driver_id', '!=', false]
                                        ],
                                        fields: ['id', 'code', 'driver_id', 'truck_id', 'status', 'container_number',
                                                'plan_booking_bill_no', 'actual_source_location_id', 'actual_destination_location_id'],
                                        limit: 1000
                                    }
                                }
                            })
                        });

                        const result = await response.json();
                        console.log('Active trips response:', result);

                        if (result.result) {
                            allTripsData = result.result;
                            displayActiveTrips(allTripsData);
                        }
                    } catch (error) {
                        console.error('Error loading active trips:', error);
                    }
                }

                // Display Active Trips Table
                function displayActiveTrips(trips) {
                    const content = document.getElementById('active-trips-content');
                    document.getElementById('active-trips-count').textContent = trips.length;

                    if (trips.length === 0) {
                        content.innerHTML = `



📭

Không có active trips nào

                        `;
                        return;
                    }

                    let tableHTML = `




                                    Trip Code
                                    Driver
                                    Vehicle
                                    Status
                                    Container
                                    Booking/Bill
                                    Route
                                    Action



                    `;

                    trips.forEach(trip => {
                        const statusClass = 'status-' + (trip.status || 'draft').replace('_', '-');
                        const statusText = (trip.status || 'draft').replace('_', ' ').toUpperCase();
                        const driverName = trip.driver_id ? trip.driver_id[1] : 'N/A';
                        const vehicleName = trip.truck_id ? trip.truck_id[1] : 'N/A';
                        const fromLocation = trip.actual_source_location_id ? trip.actual_source_location_id[1] : 'N/A';
                        const toLocation = trip.actual_destination_location_id ? trip.actual_destination_location_id[1] : 'N/A';

                        tableHTML += `


                                ${trip.code || 'Trip-' + trip.id}
                                ${driverName}
                                ${vehicleName}
                                ${statusText}
                                ${trip.container_number || '-'}
                                ${trip.plan_booking_bill_no || '-'}
                                ${fromLocation} → ${toLocation}


                                        🔗 Open



                        `;
                    });

                    tableHTML += `


                    `;

                    content.innerHTML = tableHTML;
                }

                // Load Missing Location Trips
                async function loadMissingLocationTrips() {
                    try {
                        const response = await fetch('/web/dataset/call_kw/trucking_planning.trip/search_read', {
                            method: 'POST',
                            headers: {
                                'Content-Type': 'application/json',
                            },
                            body: JSON.stringify({
                                jsonrpc: '2.0',
                                method: 'call',
                                params: {
                                    model: 'trucking_planning.trip',
                                    method: 'search_read',
                                    args: [],
                                    kwargs: {
                                        domain: [
                                            ['is_current', '=', true],
                                            ['status', 'not in', ['cancelled', 'done']],
                                            ['driver_id', '!=', false],
                                            '|', '|', '|',
                                            ['actual_source_location_id.latitude', '=', false],
                                            ['actual_source_location_id.longitude', '=', false],
                                            ['actual_destination_location_id.latitude', '=', false],
                                            ['actual_destination_location_id.longitude', '=', false]
                                        ],
                                        fields: ['id', 'code', 'driver_id', 'truck_id', 'status', 'container_number',
                                                'plan_booking_bill_no', 'actual_source_location_id', 'actual_destination_location_id'],
                                        limit: 1000
                                    }
                                }
                            })
                        });

                        const result = await response.json();
                        console.log('Missing location trips response:', result);

                        if (result.result) {
                            displayMissingLocationTrips(result.result);
                        }
                    } catch (error) {
                        console.error('Error loading missing location trips:', error);
                    }
                }

                // Display Missing Location Trips Table
                function displayMissingLocationTrips(trips) {
                    const content = document.getElementById('missing-location-content');
                    document.getElementById('missing-trips-count').textContent = trips.length;

                    if (trips.length === 0) {
                        content.innerHTML = `



✅

Tất cả trips đều có đầy đủ location!

                        `;
                        return;
                    }

                    let tableHTML = `




                                    Trip Code
                                    Driver
                                    Vehicle
                                    Status
                                    Container
                                    Missing Info
                                    Action



                    `;

                    trips.forEach(trip => {
                        const statusClass = 'status-' + (trip.status || 'draft').replace('_', '-');
                        const statusText = (trip.status || 'draft').replace('_', ' ').toUpperCase();
                        const driverName = trip.driver_id ? trip.driver_id[1] : 'N/A';
                        const vehicleName = trip.truck_id ? trip.truck_id[1] : 'N/A';

                        tableHTML += `


                                ${trip.code || 'Trip-' + trip.id}
                                ${driverName}
                                ${vehicleName}
                                ${statusText}
                                ${trip.container_number || '-'}
                                ⚠️ Missing GPS coordinates


                                        🔗 Open & Fix



                        `;
                    });

                    tableHTML += `


                    `;

                    content.innerHTML = tableHTML;
                }
                function getMarkerIcon(status, driverName = '', vehiclePlate = '') {
                    let iconHtml = '';
                    let color = '';

                    if (status === 'fresh') {
                        iconHtml = '🚛';
                        color = '#22c55e'; // Green
                    } else if (status === 'stale') {
                        iconHtml = '🚛';
                        color = '#f59e0b'; // Orange
                    } else {
                        iconHtml = '🚛';
                        color = '#ef4444'; // Red
                    }

                    return L.divIcon({
                        html: `


                                ${iconHtml}



${driverName.substring(0, 12)}

${vehiclePlate.substring(0, 10)}


                        `,
                        className: 'custom-vehicle-marker',
                        iconSize: [45, 65],
                        iconAnchor: [22, 32],
                        popupAnchor: [0, -32]
                    });
                }

                // Format popup content
                function formatPopup(location) {
                    const statusClass = 'status-' + location.status;
                    const statusText = location.status === 'fresh' ? 'New Updated' :
                                     location.status === 'stale' ? 'Stale' : 'Long Updated';

                    return `



🚛 ${location.vehicle_name}


                                👤 Driver:
                                ${location.driver_name}



                                🚚 Vehicle Plate:
                                ${location.vehicle_plate || 'N/A'}



                                📋 Trip:
                                ${location.trip_code}



                                📞 Phone:
                                ${location.driver_phone || 'N/A'}



                                📍 Status:
                                ${statusText}



                                🕐 Last Update:
                                ${location.minutes_ago} min ago

                            ${location.container_number ? `


                                📦 Container:
                                ${location.container_number}

                            ` : ''}

                    `;
                }
                function getStartIcon() {
                    return L.divIcon({
                        className: 'custom-marker',
                        html: '🚩
Start',
                        iconSize: [25, 35],
                        iconAnchor: [12, 35]
                    });
                }

                // Icon cho Destination (đỏ)
                function getDestIcon() {
                    return L.divIcon({
                        className: 'custom-marker',
                        html: '🎯
Dest',
                        iconSize: [25, 35],
                        iconAnchor: [12, 35]
                    });
                }

                // Popup cho Start
                function formatStartPopup(location) {
                    return `



🚩 Điểm Xuất Phát


                                📍 Name:
                                ${location.start_name}



                                📍 Address:
                                ${location.start_address}



                                📍 Contact Phone:
                                ${location.start_contact_phone}



                                📱 Driver:
                                ${location.driver_name}



                                🚛 Trip:
                                ${location.trip_code}


                    `;
                }

                // Popup cho Destination
                function formatDestPopup(location) {
                    return `



🎯 Điểm Đến


                                📍 Name:
                                ${location.dest_name}



                                📍 Address:
                                ${location.dest_address}



                                📍 Contact Phone:
                                ${location.dest_contact_phone}



                                📱 Driver:
                                ${location.driver_name}



                                🚛 Trip:
                                ${location.trip_code}


                    `;
                }
                // Hàm vẽ route bằng OSRM
                async function drawRoute(tripId, startLat, startLng, currentLat, currentLng, destLat, destLng) {
                    try {
                        // Xóa route cũ nếu có
                        if (routeLines[tripId]) {
                            map.removeLayer(routeLines[tripId]);
                            delete routeLines[tripId];
                        }

                        // Tạo mảng các điểm: Start -> Current -> Dest
                        const waypoints = [];
                        if (startLat && startLng) {
                            waypoints.push(`${startLng},${startLat}`);
                        }
                        if (currentLat && currentLng) {
                            waypoints.push(`${currentLng},${currentLat}`);
                        }
                        if (destLat && destLng) {
                            waypoints.push(`${destLng},${destLat}`);
                        }

                        // Cần ít nhất 2 điểm để vẽ route
                        if (waypoints.length < 2) {
                            console.log(`Trip ${tripId}: Không đủ điểm để vẽ route`);
                            return;
                        }

                        // Gọi OSRM API (free server)
                        const osrmUrl = `https://router.project-osrm.org/route/v1/driving/${waypoints.join(';')}?overview=full&geometries=geojson`;

                        const response = await fetch(osrmUrl);
                        const data = await response.json();

                        if (data.code === 'Ok' && data.routes && data.routes.length > 0) {
                            const route = data.routes[0];
                            const coordinates = route.geometry.coordinates;

                            // Chuyển đổi coordinates từ [lng, lat] sang [lat, lng] cho Leaflet
                            const latLngs = coordinates.map(coord => [coord[1], coord[0]]);

                            // Vẽ polyline lên map
                            const routeLine = L.polyline(latLngs, {
                                color: '#2563eb',
                                weight: 4,
                                opacity: 0.7,
                                lineJoin: 'round'
                            }).addTo(map);

                            // Thêm popup với thông tin route
                            const distance = (route.distance / 1000).toFixed(1); // km
                            const duration = (route.duration / 60).toFixed(0); // phút
                            routeLine.bindPopup(`
                                Route Info

                                Distance: ${distance} km

                                Duration: ${duration} minutes
                            `);


                            // Lưu lại để có thể xóa sau
                            routeLines[tripId] = routeLine;

                            console.log(`✅ Đã vẽ route cho trip ${tripId}: ${distance}km, ${duration}min`);
                        } else {
                            console.warn(`⚠️ OSRM không tìm thấy route cho trip ${tripId}`);
                        }
                    } catch (error) {
                        console.error(`❌ Lỗi khi vẽ route cho trip ${tripId}:`, error);
                    }
                }
                // Fetch and update driver locations
                async function fetchDriverLocations() {
                    try {
                        const response = await fetch('/vehicle_tracking/api/driver_locations', {
                            method: 'POST',
                            headers: {
                                'Content-Type': 'application/json',
                            },
                            body: JSON.stringify({
                                jsonrpc: '2.0',
                                method: 'call',
                                params: {}
                            })
                        });

                        const result = await response.json();

                        if (result.result && result.result.success) {
                            console.log('✅ API Success - Found', result.result.data.length, 'locations');
                            console.log('📍 Location data:', result.result.data);
                            updateMarkers(result.result.data);
                            updateStats(result.result.data);
                            updateLastRefreshTime();
                        } else {
                            console.error('❌ Failed to fetch driver locations:', result);
                        }
                    } catch (error) {
                        console.error('Error fetching driver locations:', error);
                    }
                }

                // Update markers on map
                function updateMarkers(locations) {
                    // Remove old markers that no longer exist
                    Object.keys(markers).forEach(driverId => {
                        if (!locations.find(loc => loc.driver_id == driverId)) {
                            map.removeLayer(markers[driverId]);
                            delete markers[driverId];
                        }
                    });
                    Object.keys(startMarkers).forEach(tripId => {
                        if (!locations.find(loc => loc.trip_id == tripId)) {
                            map.removeLayer(startMarkers[tripId]);
                            delete startMarkers[tripId];
                        }
                    });
                    Object.keys(destMarkers).forEach(tripId => {
                        if (!locations.find(loc => loc.trip_id == tripId)) {
                            map.removeLayer(destMarkers[tripId]);
                            delete destMarkers[tripId];
                        }
                    });
                    // Remove old routes that no longer exist
                    Object.keys(routeLines).forEach(tripId => {
                        if (!locations.find(loc => loc.trip_id == tripId)) {
                            map.removeLayer(routeLines[tripId]);
                            delete routeLines[tripId];
                        }
                    });
                    // Add or update markers
                    locations.forEach(location => {
                        const driverId = location.driver_id;
                        if (location.latitude && location.longitude) {  // Current
                            if (markers[driverId]) {
                                markers[driverId].setLatLng([location.latitude, location.longitude]);
                                markers[driverId].setPopupContent(formatPopup(location));
                            } else {
                                const marker = L.marker([location.latitude, location.longitude], {
                                    icon: getMarkerIcon(location.status, location.driver_name, location.vehicle_plate)
                                }).addTo(map);
                                marker.bindPopup(formatPopup(location));
                                markers[driverId] = marker;
                            }
                        }

                        const tripId = location.trip_id;
                        // Start marker
                        if (location.start_lat && location.start_lng) {
                            if (startMarkers[tripId]) {
                                startMarkers[tripId].setLatLng([location.start_lat, location.start_lng]);
                            } else {
                                const startMarker = L.marker([location.start_lat, location.start_lng], { icon: getStartIcon() }).addTo(map);
                                startMarker.bindPopup(formatStartPopup(location));
                                startMarkers[tripId] = startMarker;
                            }
                        }

                        // Dest marker
                        if (location.dest_lat && location.dest_lng) {
                            if (destMarkers[tripId]) {
                                destMarkers[tripId].setLatLng([location.dest_lat, location.dest_lng]);
                            } else {
                                const destMarker = L.marker([location.dest_lat, location.dest_lng], { icon: getDestIcon() }).addTo(map);
                                destMarker.bindPopup(formatDestPopup(location));
                                destMarkers[tripId] = destMarker;
                            }
                        }
                        // Vẽ route nếu có đủ thông tin
                        if (location.start_lat && location.start_lng &&
                            location.dest_lat && location.dest_lng) {
                            drawRoute(
                                tripId,
                                location.start_lat,
                                location.start_lng,
                                location.latitude,
                                location.longitude,
                                location.dest_lat,
                                location.dest_lng
                            );
                        }
                    });


                    // Fit bounds tất cả
                    if (locations.length > 0) {
                        const allMarkers = [...Object.values(markers), ...Object.values(startMarkers), ...Object.values(destMarkers)].filter(m => m);
                        if (allMarkers.length > 0) {
                            const group = new L.featureGroup(allMarkers);
                            map.fitBounds(group.getBounds().pad(0.1));
                        }
                    }
                }

                async function updateStats(locations) {
                    const freshCount = locations.filter(loc => loc.status === 'fresh').length;
                    const staleCount = locations.filter(loc => loc.status === 'old').length;

                    // Fetch statistics from backend to get missing location count
                    try {
                        const response = await fetch('/web/dataset/call_kw/vehicle.tracking.service/get_tracking_statistics', {
                            method: 'POST',
                            headers: {
                                'Content-Type': 'application/json',
                            },
                            body: JSON.stringify({
                                jsonrpc: '2.0',
                                method: 'call',
                                params: {
                                    model: 'vehicle.tracking.service',
                                    method: 'get_tracking_statistics',
                                    args: [],
                                    kwargs: {}
                                }
                            })
                        });

                        const result = await response.json();

                        if (result.result) {
                            const stats = result.result;
                            document.getElementById('stat-active').textContent = stats.active_trips;
                            document.getElementById('stat-fresh').textContent = freshCount;
                            document.getElementById('stat-stale').textContent = staleCount;

                            // Update missing location count
                            const missingElement = document.getElementById('stat-missing');
                            if (stats.missing_location > 0) {
                                missingElement.textContent = `(${stats.missing_location} missing location)`;
                                missingElement.style.display = 'block';
                            } else {
                                missingElement.textContent = '';
                                missingElement.style.display = 'none';
                            }
                        }
                    } catch (error) {
                        console.error('Error fetching statistics:', error);
                        // Fallback to basic stats
                        document.getElementById('stat-active').textContent = locations.length;
                        document.getElementById('stat-fresh').textContent = freshCount;
                        document.getElementById('stat-stale').textContent = staleCount;
                        document.getElementById('stat-missing').textContent = '';
                    }
                }

                // Update last refresh time
                function updateLastRefreshTime() {
                    const now = new Date();
                    document.getElementById('last-refresh').textContent =
                        `Last updated: ${now.toLocaleTimeString()}`;
                }

                // Manual refresh with loading indicator
                function refreshMap() {
                    // Show loading state
                    const refreshBtn = document.querySelector('.btn-primary');
                    const originalText = refreshBtn.innerHTML;
                    refreshBtn.innerHTML = '⏳ Loading...';
                    refreshBtn.disabled = true;

                    // Fetch data
                    fetchDriverLocations().finally(() => {
                        // Restore button state after a short delay
                        setTimeout(() => {
                            refreshBtn.innerHTML = '🔄 Refresh Now';
                            refreshBtn.disabled = false;
                        }, 500);
                    });
                }


                // Auto-refresh toggle
                document.getElementById('auto-refresh-toggle').addEventListener('change', function(e) {
                    if (e.target.checked) {
                        startAutoRefresh();
                    } else {
                        stopAutoRefresh();
                    }
                });

                // Start auto-refresh
                function startAutoRefresh() {
                    if (autoRefreshInterval) {
                        clearInterval(autoRefreshInterval);
                    }
                    autoRefreshInterval = setInterval(fetchDriverLocations, 30000); // 30 seconds
                }

                // Stop auto-refresh
                function stopAutoRefresh() {
                    if (autoRefreshInterval) {
                        clearInterval(autoRefreshInterval);
                        autoRefreshInterval = null;
                    }
                }

                // Search functionality
                document.getElementById('search-box')?.addEventListener('input', function(e) {
                    const searchText = e.target.value.toLowerCase();

                    // Start markers
                    Object.entries(startMarkers).forEach(([tripId, marker]) => {
                        const popup = marker.getPopup();
                        if (popup) {
                            const content = popup.getContent().toLowerCase();
                            marker.setOpacity(content.includes(searchText) ? 1 : (searchText === '' ? 1 : 0.3));
                        }
                    });

                    // Dest markers
                    Object.entries(destMarkers).forEach(([tripId, marker]) => {
                        const popup = marker.getPopup();
                        if (popup) {
                            const content = popup.getContent().toLowerCase();
                            marker.setOpacity(content.includes(searchText) ? 1 : (searchText === '' ? 1 : 0.3));
                        }
                    });

                    // Current markers
                    Object.entries(markers).forEach(([driverId, marker]) => {
                        const popup = marker.getPopup();
                        if (popup) {
                            const content = popup.getContent().toLowerCase();
                            marker.setOpacity(content.includes(searchText) ? 1 : (searchText === '' ? 1 : 0.3));
                        }
                    });
                });

                // Initial load
                fetchDriverLocations();
                startAutoRefresh();
